[DataContract]
class OMGTutorialInboundDataContract extends OMGDataContract
{
    private name        ftpServerAddress;
    private UserName    userName;
    private name        password;

}

Method.Source:
public ClassId validationClassId()
{
    // TODO We need a non azure validator class
    // TODO Do we need this method? The validate method calls a specific class anyway....
    return classNum(OMGTutorialInboundValidator);
}

[DataMember, SysOperationDisplayOrder('1'), SysOperationLabel("FTP server")]
public Name parmFtpServerAddress(Name _ftpServerAddress = ftpServerAddress)
{
    ftpServerAddress = _ftpServerAddress;
    return ftpServerAddress;
}

[DataMember, SysOperationDisplayOrder('2')]
public UserName parmUserName(UserName _userName = userName)
{
    userName = _userName;
    return userName;
}

[DataMember, SysOperationDisplayOrder('3')]
public name parmPassword(Name _password = password)
{
    password = _password;
    return password;
}
